import java.io.Serializable;
import java.io.ObjectOutputStream;
import java.io.ObjectInputStream;
import java.io.FileOutputStream;
import java.io.FileInputStream;
import java.io.IOException;

public class Main {
    public static void main(String[] args) {
        Persona p = new Persona("Ana", 25);

        // Serializar
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream("persona.dat"))) {
            oos.writeObject(p);
            System.out.println("Persona serializada");
        } catch (IOException e) {
            System.out.println("Error al serializar: " + e.getMessage());
        }

        // Deserializar
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream("persona.dat"))) {
            Persona cargada = (Persona) ois.readObject();
            System.out.println("Nombre: " + cargada.nombre + ", Edad: " + cargada.edad);
        } catch (IOException | ClassNotFoundException e) {
            System.out.println("Error al deserializar: " + e.getMessage());
        }
    }
}

class Persona implements Serializable {
    String nombre;
    int edad;
    Persona(String nombre, int edad) {
        this.nombre = nombre;
        this.edad = edad;
    }
}

