import java.io.Serializable;
import java.io.ObjectOutputStream;
import java.io.ObjectInputStream;
import java.io.FileOutputStream;
import java.io.FileInputStream;
import java.io.IOException;

public class Main {
    public static void main(String[] args) {
        Cuenta cuenta = new Cuenta("Juan", 5000.0, "SECRET123");

        System.out.println("=== Antes de serializar ===");
        System.out.println("Titular: " + cuenta.titular);
        System.out.println("Saldo: " + cuenta.saldo);
        System.out.println("Password: " + cuenta.password);

        // Serializar
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream("cuenta.dat"))) {
            oos.writeObject(cuenta);
        } catch (IOException e) {
            System.out.println("Error: " + e.getMessage());
        }

        // Deserializar
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream("cuenta.dat"))) {
            Cuenta cargada = (Cuenta) ois.readObject();
            System.out.println("\n=== Después de deserializar ===");
            System.out.println("Titular: " + cargada.titular);
            System.out.println("Saldo: " + cargada.saldo);
            System.out.println("Password: " + cargada.password);
        } catch (IOException | ClassNotFoundException e) {
            System.out.println("Error: " + e.getMessage());
        }
    }
}

class Cuenta implements Serializable {
    String titular;
    double saldo;
    transient String password;
    Cuenta(String titular, double saldo, String password) {
        this.titular = titular;
        this.saldo = saldo;
        this.password = password;
    }
}
